{
  "title": "Suspicious Kerberos Auth Success After Failure",
  "id": "e3b9f6d2-8c1a-4f5e-9a2d-3c7f9b1a2d4e",
  "status": "experimental",
  "description": "Detects a successful Kerberos TGT request from a source IP that previously generated a failed pre-authentication event for the same user within 5 minutes, indicating possible credential guessing or pass-the-hash.",
  "author": "SOC Team",
  "logsource": {
    "product": "windows",
    "service": "security"
  },
  "detection": {
    "selection_failure": {
      "EventID": 4771,
      "Outcome": "failure"
    },
    "selection_success": {
      "EventID": 4768,
      "Outcome": "success"
    },
    "condition": "selection_failure and selection_success and selection_failure.user = selection_success.user and selection_failure.src_ip = selection_success.src_ip and selection_success.@timestamp - selection_failure.@timestamp <= 5m"
  },
  "level": "high",
  "tags": ["attack.t1110", "credential-access", "kerberos"]
}
